create table if not exists rental_support_cases(owner_id text not null,id text not null,tenant_id text,lease_id text,payment_id text,case_type text not null check(case_type in('failed_payment','refund_request','payment_dispute','portal_access','maintenance_escalation','other')),priority text not null default 'normal'check(priority in('normal','high','urgent')),status text not null default 'open'check(status in('open','investigating','waiting_on_tenant','waiting_on_provider','resolved','closed')),title text not null,tenant_visible_summary text,private_owner_note text,resolution text,opened_at timestamptz not null default now(),resolved_at timestamptz,closed_at timestamptz,created_by text not null,updated_at timestamptz not null default now(),primary key(owner_id,id),foreign key(owner_id,tenant_id)references rental_tenants(owner_id,id),foreign key(owner_id,lease_id)references rental_leases(owner_id,id),foreign key(owner_id,payment_id)references rental_payments(owner_id,id));
create table if not exists rental_support_case_events(owner_id text not null,id text not null,case_id text not null,event_type text not null check(event_type in('opened','status_changed','tenant_update','private_note','provider_update','resolved','closed','reopened')),public_note text,private_note text,status text,occurred_at timestamptz not null default now(),recorded_by text not null,primary key(owner_id,id),foreign key(owner_id,case_id)references rental_support_cases(owner_id,id));
alter table rental_support_cases enable row level security;alter table rental_support_cases force row level security;alter table rental_support_case_events enable row level security;alter table rental_support_case_events force row level security;
create policy rental_support_owner_all on rental_support_cases for all to authenticated using(owner_id=auth.uid()::text)with check(owner_id=auth.uid()::text);create policy rental_support_event_owner_all on rental_support_case_events for all to authenticated using(owner_id=auth.uid()::text)with check(owner_id=auth.uid()::text);
create policy rental_support_tenant_read on rental_support_cases for select to authenticated using(tenant_id is not null and exists(select 1 from rental_tenants t where t.owner_id=rental_support_cases.owner_id and t.id=rental_support_cases.tenant_id and t.auth_user_id=auth.uid()));
create policy rental_support_event_tenant_read on rental_support_case_events for select to authenticated using(public_note is not null and exists(select 1 from rental_support_cases c join rental_tenants t on t.owner_id=c.owner_id and t.id=c.tenant_id where c.owner_id=rental_support_case_events.owner_id and c.id=rental_support_case_events.case_id and t.auth_user_id=auth.uid()));
create or replace function update_rental_support_case(p_owner_id text,p_case_id text,p_status text,p_public_note text,p_private_note text,p_resolution text)returns rental_support_cases language plpgsql security invoker set search_path=public as $$declare result rental_support_cases;event_name text;begin if p_owner_id<>auth.uid()::text or p_status not in('open','investigating','waiting_on_tenant','waiting_on_provider','resolved','closed')then raise exception 'Owner support update is invalid.';end if;event_name:=case when p_status='resolved'then'resolved'when p_status='closed'then'closed'else'status_changed'end;update rental_support_cases set status=p_status,tenant_visible_summary=coalesce(nullif(btrim(p_public_note),''),tenant_visible_summary),private_owner_note=coalesce(nullif(btrim(p_private_note),''),private_owner_note),resolution=case when p_status in('resolved','closed')then nullif(btrim(p_resolution),'')else resolution end,resolved_at=case when p_status='resolved'then now()else resolved_at end,closed_at=case when p_status='closed'then now()else closed_at end,updated_at=now()where owner_id=p_owner_id and id=p_case_id returning * into result;if result.id is null then raise exception 'Support case was not found.';end if;insert into rental_support_case_events(owner_id,id,case_id,event_type,public_note,private_note,status,recorded_by)values(p_owner_id,'rental_support_event_'||gen_random_uuid()::text,p_case_id,event_name,nullif(btrim(p_public_note),''),nullif(btrim(p_private_note),''),p_status,auth.uid()::text);return result;end$$;
grant execute on function update_rental_support_case(text,text,text,text,text,text)to authenticated;
create or replace function open_rental_payment_support_case()returns trigger language plpgsql security definer set search_path=public set row_security=off as $$declare v_type text;begin if new.status not in('failed','disputed','partially_refunded','refunded')or new.status is not distinct from old.status then return new;end if;v_type:=case when new.status='failed'then'failed_payment'when new.status='disputed'then'payment_dispute'else'refund_request'end;insert into rental_support_cases(owner_id,id,tenant_id,lease_id,payment_id,case_type,priority,title,tenant_visible_summary,created_by)select new.owner_id,'rental_support_case_'||gen_random_uuid()::text,new.tenant_id,new.lease_id,new.id,v_type,case when new.status='disputed'then'high'else'normal'end,case when new.status='failed'then'Payment needs attention'when new.status='disputed'then'Payment dispute review'else'Refund follow-up'end,case when new.status='failed'then'Your payment did not complete. The landlord is reviewing the payment status.'when new.status='disputed'then'A payment dispute is under review.'else'A refund adjustment is being reviewed.'end,new.owner_id where not exists(select 1 from rental_support_cases c where c.owner_id=new.owner_id and c.payment_id=new.id and c.case_type=v_type and c.status not in('closed'));return new;end$$;
drop trigger if exists open_rental_payment_support_case_trigger on rental_payments;create trigger open_rental_payment_support_case_trigger after update of status on rental_payments for each row execute function open_rental_payment_support_case();revoke all on function open_rental_payment_support_case()from public,anon,authenticated;
